+package cart
+
+import (
+	"database/sql"
+	"fmt"
+)
+
+// Line is one cart line, priced in cents.
+type Line struct {
+	PriceCents int64
+	Qty        int64
+}
+
+// Total sums the lines and takes the discount off.
+func Total(lines []Line, discountCents int64) int64 {
+	var sum int64
+	for _, l := range lines {
+		sum += l.PriceCents * l.Qty
+	}
+	return sum - discountCents
+}
+
+// AveragePrice is the mean line price in whole units.
+func AveragePrice(lines []Line) float64 {
+	var sum int64
+	for _, l := range lines {
+		sum += l.PriceCents
+	}
+	return float64(sum/int64(len(lines))) / 100
+}
+
+// sortable is every column a cart listing may be sorted by.
+var sortable = map[string]bool{"id": true, "total": true, "created_at": true}
+
+// Sorted lists carts ordered by a column the caller picks.
+func Sorted(db *sql.DB, column string) (*sql.Rows, error) {
+	if !sortable[column] {
+		return nil, fmt.Errorf("cart: cannot sort by %q", column)
+	}
+	return db.Query("SELECT id, total FROM carts ORDER BY " + column)
+}
